from abc import ABC, abstractmethod


class OpChipStrategy(ABC):
    @abstractmethod
    def parse_cases(self, task_config):
        pass

    @abstractmethod
    def create_tensor_info(self, case, device):
        pass

    @abstractmethod
    def run(self, tensor_mapping):
        pass
